using System;using System.Collections.Generic;using System.Linq;using UnityEngine;using UnityEngine.SceneManagement;
// Presentation of the isolated home; time/weather remain owned by WorldSession/GridShiftWeather.
[DefaultExecutionOrder(1000)]
public sealed class GridShiftHomeEnvironment:MonoBehaviour {
 [Serializable]public sealed class Room {public string id;[HideInInspector]public Vector3 at;public bool defaultOn;public Light light;public Renderer rocker;public GridShiftWorldAction action;public float dayIntensity=2,nightIntensity=3.2f;public Quaternion rockerBase=Quaternion.identity;}
 [SerializeField]List<ParticleSystem> rains=new List<ParticleSystem>();[SerializeField]List<Room> rooms=new List<Room>();[SerializeField]bool sceneAuthored;readonly List<Material> owned=new List<Material>();[SerializeField]Light daylight;[SerializeField]Camera homeCamera;bool built;public int SwitchCount=>rooms.Count;
 void Start(){Build();}
 Material Material(Color color){var m=new Material(Shader.Find("Universal Render Pipeline/Lit")){color=color};owned.Add(m);return m;}
 GameObject Cube(string name,Transform parent,Vector3 at,Vector3 size,Material material,bool solid=false){var go=GameObject.CreatePrimitive(PrimitiveType.Cube);go.name=name;go.transform.SetParent(parent,false);go.transform.localPosition=at;go.transform.localScale=size;go.GetComponent<Renderer>().sharedMaterial=material;go.GetComponent<Collider>().enabled=solid;return go;}
 public void Build(){if(built)return;built=true;if(sceneAuthored){foreach(var room in rooms){var bound=room;room.action.action=p=>{Toggle(bound.id);return true;};}return;}foreach(var effect in GetComponentsInChildren<ParticleSystem>(true))effect.gameObject.layer=12;ClearWindowGlass();
 foreach(var l in gameObject.scene.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<Light>(true))){if(l.type==LightType.Directional)daylight=l;else l.enabled=false;}
 homeCamera=gameObject.scene.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<Camera>(true)).FirstOrDefault(c=>c.GetComponentInParent<PlayerMovement>()!=null);
 var root=new GameObject("Home skyline backdrop").transform;root.SetParent(transform,false);var palette=new[]{Material(new Color(.24f,.3f,.37f)),Material(new Color(.34f,.37f,.4f)),Material(new Color(.27f,.32f,.4f))};for(int i=0;i<24;i++){float angle=i*Mathf.PI*2/24;float height=14+(i*17%24);var at=new Vector3(-8+Mathf.Cos(angle)*65,-24+height*.5f,Mathf.Sin(angle)*65);Cube("Distant residential silhouette",root,at,new Vector3(10,height,10),palette[i%3]);}Cube("Distant horizon ground",root,new Vector3(-8,-25,0),new Vector3(250,1,250),palette[0]);
 foreach(var t in root.GetComponentsInChildren<Transform>())t.gameObject.layer=12;BuildRain();Add("Sala",new Vector3(2,2.6f,-3),true);Add("Cozinha",new Vector3(2,2.6f,6.5f),false);Add("Circulação",new Vector3(-12,2.6f,1.8f),true);Add("Quarto casal",new Vector3(-19,2.6f,-5),false);Add("Quarto 1",new Vector3(-8,2.6f,7),false);Add("Quarto 2",new Vector3(-17.5f,2.6f,7),false);Add("Banheiro",new Vector3(-8,2.6f,-2.5f),false);Add("Banheiro suíte",new Vector3(-20,2.6f,2.7f),false);
 }
 public void AuthorScene(){Build();sceneAuthored=true;foreach(var room in rooms){room.action.sceneAuthored=true;room.rockerBase=room.rocker.transform.localRotation;}}
 void ClearWindowGlass(){var windows=transform.Find("Apartment_01/Windows");if(windows==null)return;var clones=new Dictionary<Material,Material>();foreach(var renderer in windows.GetComponentsInChildren<Renderer>(true)){var slots=renderer.sharedMaterials;for(int i=0;i<slots.Length;i++){var source=slots[i];if(source==null||source.name=="Home window clear glass"||source.name.IndexOf("Glass",StringComparison.OrdinalIgnoreCase)<0)continue;if(!clones.TryGetValue(source,out var clear)){clear=new Material(source){name="Home window clear glass"};clear.SetFloat("_Smoothness",.06f);clear.SetFloat("_EnvironmentReflections",0);clear.SetFloat("_SpecularHighlights",0);clear.EnableKeyword("_ENVIRONMENTREFLECTIONS_OFF");clear.EnableKeyword("_SPECULARHIGHLIGHTS_OFF");clear.SetColor("_BaseColor",new Color(.82f,.9f,1,.06f));owned.Add(clear);clones[source]=clear;}slots[i]=clear;}renderer.sharedMaterials=slots;}}
 void BuildRain(){var template=Resources.Load<Material>("GridShiftRain20");if(template==null)return;for(int i=0;i<4;i++){var go=new GameObject("Rain beyond home windows");go.layer=12;go.transform.SetParent(transform,false);go.transform.localPosition=i<2?new Vector3(-8,14,i==0?-18:18):new Vector3(i==2?-33:18,14,0);go.transform.rotation=Quaternion.Euler(90,0,0);var p=go.AddComponent<ParticleSystem>();p.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);var main=p.main;main.loop=true;main.startLifetime=2;main.startSpeed=18;main.startSize=.035f;main.startColor=new Color(.6f,.75f,.9f,.65f);main.simulationSpace=ParticleSystemSimulationSpace.World;main.maxParticles=1600;var emission=p.emission;emission.rateOverTime=600;var shape=p.shape;shape.shapeType=ParticleSystemShapeType.Box;shape.scale=i<2?new Vector3(50,1,1):new Vector3(1,35,1);var renderer=p.GetComponent<ParticleSystemRenderer>();renderer.sharedMaterial=template;renderer.renderMode=ParticleSystemRenderMode.Stretch;renderer.lengthScale=4;rains.Add(p);}}
 void Add(string id,Vector3 at,bool defaultOn){var r=new Room{id=id,at=at,defaultOn=defaultOn};var g=new GameObject("Room light · "+id,typeof(Light));g.transform.SetParent(transform,false);g.transform.localPosition=at;r.light=g.GetComponent<Light>();r.light.type=LightType.Point;r.light.range=8;r.light.intensity=3;r.light.color=new Color(1,.84f,.66f);r.light.shadows=LightShadows.None;rooms.Add(r);
 var origin=transform.TransformPoint(new Vector3(at.x,1.3f,at.z));RaycastHit best=new RaycastHit();bool found=false;float nearest=100;foreach(var direction in new[]{Vector3.forward,Vector3.back,Vector3.right,Vector3.left})foreach(var hit in Physics.RaycastAll(origin,direction,15,~((1<<7)|(1<<8)|(1<<9)),QueryTriggerInteraction.Ignore)){if(!hit.transform.IsChildOf(transform)||!hit.transform.name.Contains("Wall")||Mathf.Abs(hit.normal.y)>.2f||hit.distance>=nearest)continue;best=hit;nearest=hit.distance;found=true;}
 var point=found?best.point+best.normal*.035f:origin+Vector3.left;var mount=new GameObject("Light switch · "+id).transform;mount.SetParent(transform,false);mount.position=point;mount.rotation=Quaternion.LookRotation(found?best.normal:Vector3.forward);var plate=Cube("Switch plate",mount,Vector3.zero,new Vector3(.14f,.22f,.035f),Material(new Color(.85f,.86f,.83f)),true);var rocker=Cube("Switch rocker",mount,new Vector3(0,0,.027f),new Vector3(.075f,.12f,.025f),Material(new Color(.9f,.75f,.25f)),false);r.rocker=rocker.GetComponent<Renderer>();var action=GridShiftWorldAction.Create(mount,"Alternar luz · "+id,Vector3.zero,p=>{Toggle(id);return true;});r.action=action;GridShiftApartment.NormalizeFocus(action.transform);action.focusOwner=plate.transform;action.sightRoot=mount;action.focusOffset=Vector3.zero;action.focusRadius=.15f;action.range=2.8f;
 }
 public bool IsOn(string id){var state=GridShiftLife.Instance?.State;if(state?.lightOnRooms?.Contains(id)==true)return true;if(state?.lightOffRooms?.Contains(id)==true)return false;return rooms.First(r=>r.id==id).defaultOn;}
 public void Toggle(string id){var life=GridShiftLife.Instance;if(life==null)return;bool on=!IsOn(id);var yes=(life.State.lightOnRooms??Array.Empty<string>()).Where(s=>s!=id).ToList();var no=(life.State.lightOffRooms??Array.Empty<string>()).Where(s=>s!=id).ToList();(on?yes:no).Add(id);life.State.lightOnRooms=yes.ToArray();life.State.lightOffRooms=no.ToArray();life.Changed();}
 void LateUpdate(){if(!built||SceneManager.GetActiveScene()!=gameObject.scene)return;float hour=WorldSession.Instance?.ClockHour??12;float sun=Mathf.SmoothStep(0,1,Mathf.Clamp01((hour-5)/2))*Mathf.SmoothStep(0,1,Mathf.Clamp01((19-hour)/2));float cloud=GridShiftWeather.Description=="Chuva"?.4f:GridShiftWeather.Description=="Nublado"?.65f:1;var sky=Color.Lerp(new Color(.012f,.024f,.06f),new Color(.42f,.64f,.82f)*cloud,sun);RenderSettings.fogColor=sky;foreach(var rain in rains){if(GridShiftWeather.Raining){if(!rain.isEmitting)rain.Play();}else if(rain.isEmitting)rain.Stop();}if(homeCamera!=null){homeCamera.clearFlags=CameraClearFlags.SolidColor;homeCamera.backgroundColor=sky;}RenderSettings.ambientLight=Color.Lerp(new Color(.065f,.08f,.12f),new Color(.45f,.48f,.52f)*cloud,sun);if(daylight!=null)daylight.intensity=Mathf.Lerp(.035f,.6f*cloud,sun);foreach(var room in rooms){bool on=IsOn(room.id);room.light.enabled=on;room.light.intensity=on?Mathf.Lerp(room.nightIntensity,room.dayIntensity,sun):0;room.rocker.transform.localRotation=room.rockerBase*Quaternion.Euler(on?-14:14,0,0);}}
 void OnDestroy(){if(!Application.isPlaying)return;foreach(var m in owned)if(m!=null)Destroy(m);}
}
